var i=`0741-atakilt-wat`;var n=`world-0741`;var a=`ET`;var s=`eastern-africa`;var r=4;var o=44;var g={en:`Atakilt Wat`,ua:`Атакільт ват`};var l={en:`Atakilt Wat is a Ethiopia classic prepared with yellow onion, niter kibbeh, garlic, potato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Атакільт ват, страва кухні країни Ефіопія зі складниками: жовта цибуля, пряне масло нітер кіббе, часник, картопля. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,170,`g`],[`niter-kibbeh`,40,`g`],[`garlic`,4,`clove`],[`ground-turmeric`,5,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 30 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 30 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:30,i:[[`potato`,440,`g`],[`carrot`,320,`g`],[`white-cabbage`,380,`g`],[`water`,330,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`injera`,4,`pcs`],[`table-salt`,null,`to_taste`]]}];var h={slug:i,id:n,country:`ET`,region:s,servings:4,minutes:44,title:g,text:l,steps:d};export{a as country,h as default,n as id,o as minutes,s as region,r as servings,i as slug,d as steps,l as text,g as title};